/** All fields: key => [r region, t type, d default, l label, g group]. */
function nexxi_studio_fields() {
	static $fields = null;
	if ( null === $fields ) {
		$file = get_template_directory() . '/inc/studio-fields.php';
		$generated = is_readable( $file ) ? include $file : array();
		$fields = array_merge( nexxi_studio_manual_fields(), is_array( $generated ) ? $generated : array() );
	}
	return $fields;
}

/** Vietnamese names for the Stitch section comments used as field groups. */
function nexxi_studio_group_label( $group ) {
	if ( '' === $group ) { return ''; }
	$map = array(
		'Cute Tag Badge' => 'Nhãn nhỏ phía trên', 'Main Title' => 'Tiêu đề lớn', 'Subtitle' => 'Đoạn mô tả', 'CTAs' => 'Nút bấm',
		'Social Proof Bubble' => 'Khối “mẹ hài lòng”', 'Floating Cloud Sticker 1' => 'Nhãn nổi trên ảnh 1', 'Floating Cloud Sticker 2' => 'Nhãn nổi trên ảnh 2',
		'Main Cloud Shaped Framed Photo' => 'Ảnh banner chính', 'Top Bar: Header & Countdown Pill' => 'Tiêu đề & đồng hồ', 'Digital Candy Countdown Clock' => 'Đồng hồ đếm ngược',
		'Banner Title Header' => 'Tiêu đề banner', 'Left Content' => 'Nội dung bên trái', 'Countdown Component Box' => 'Hộp đếm ngược', 'Digital Counter Tiles' => 'Ô đếm giờ',
		'Right Visual Showcase' => 'Ảnh bên phải', 'Overlaid Badge' => 'Nhãn trên ảnh', 'Bottom Floating Pill' => 'Nhãn nổi dưới ảnh', 'Decorative Backdrop Circles' => 'Nội dung',
		'Form Widget' => 'Ô đăng ký', 'Playful Badge' => 'Nhãn nhỏ', 'Brand Visual Banner' => 'Ảnh thương hiệu', 'Membership Perks List' => 'Quyền lợi thành viên',
		'Bottom: Testimonial Bubble' => 'Lời chứng thực',
	);
	if ( isset( $map[ $group ] ) ) { return $map[ $group ]; }
	$patterns = array( '~^Card (\d+).*~' => 'Thẻ danh mục $1', '~^Lookbook (\d+).*~' => 'Lookbook $1', '~^Feature (\d+).*~' => 'Mục $1', '~^Slot (\d+).*~' => 'Khung giờ $1', '~^Voucher (\d+).*~' => 'Voucher $1', '~^Perk (\d+).*~' => 'Quyền lợi $1' );
	foreach ( $patterns as $re => $label ) {
		if ( preg_match( $re, $group ) ) { return preg_replace( $re, $label, $group ); }
	}
	return $group;
}

/* ------------------------------------------------------------------ values */

function nexxi_studio_saved() {
	$saved = get_theme_mod( 'nexxi_studio', array() );
	return is_array( $saved ) ? $saved : array();
}

function nexxi_studio_asset( $value ) {
	return str_replace( '{{STITCH_ASSET}}', get_template_directory_uri() . '/assets/stitch', (string) $value );
}

/** Default of a field, with asset placeholders resolved. */
function nexxi_studio_default( $key ) {
	$fields = nexxi_studio_fields();
	return isset( $fields[ $key ] ) ? nexxi_studio_asset( $fields[ $key ]['d'] ) : '';
}

/** Saved value if it differs from the default, otherwise null. */
function nexxi_studio_changed( $key ) {
	$saved = nexxi_studio_saved();
	if ( ! isset( $saved[ $key ] ) || ! is_scalar( $saved[ $key ] ) ) { return null; }
	$value = trim( (string) $saved[ $key ] );
	return ( '' === $value || $value === nexxi_studio_default( $key ) ) ? null : $value;
}

function nexxi_studio_value( $key ) {
	$changed = nexxi_studio_changed( $key );
	return null === $changed ? nexxi_studio_default( $key ) : $changed;
}

/** Escaped text plus the live-preview hook for PHP-rendered elements. */
function nexxi_studio_t( $key ) {
	return esc_html( nexxi_studio_value( $key ) );
}
function nexxi_studio_attr( $key ) {
	return ' data-nxe="' . esc_attr( $key ) . '"';
}

/** Raw setting (non-field settings such as menu slots, colours, socials). */
function nexxi_studio_opt( $key, $default = '' ) {
	$saved = nexxi_studio_saved();
	return isset( $saved[ $key ] ) && is_scalar( $saved[ $key ] ) ? (string) $saved[ $key ] : $default;
}

function nexxi_studio_region_visible( $region ) {
	return '0' !== nexxi_studio_opt( 'show_' . $region, '1' ) && '' !== nexxi_studio_opt( 'show_' . $region, '1' );
}

/** Region attribute for PHP-rendered sections. */
function nexxi_studio_region_attr( $region ) {
	return ' data-nxr="' . esc_attr( $region ) . '"';
}

/** Turn an editor link (/path, #anchor, full URL, phone) into a URL. */
function nexxi_studio_url( $value ) {
	$value = trim( (string) $value );
	if ( '' === $value ) { return ''; }
	if ( '/' === $value[0] && ( ! isset( $value[1] ) || '/' !== $value[1] ) ) { return home_url( $value ); }
	return $value;
}

/* ------------------------------------------------------------------ html helpers */

function nexxi_studio_clean( $text ) {
	$text = html_entity_decode( $text, ENT_QUOTES | ENT_HTML5, 'UTF-8' );
	return trim( preg_replace( '~\s+~u', ' ', str_replace( "\xC2\xA0", ' ', $text ) ) );
}

/** Non-empty direct text nodes between $from and $to (child elements and comments are skipped). */
function nexxi_studio_segments( $html, $from, $to ) {
	$segments = array();
	$i = $from;
	while ( $i < $to ) {
		$lt = strpos( $html, '<', $i );
		if ( false === $lt || $lt > $to ) { $lt = $to; }
		if ( $lt > $i && '' !== nexxi_studio_clean( substr( $html, $i, $lt - $i ) ) ) { $segments[] = array( $i, $lt ); }
		if ( $lt >= $to ) { break; }
		if ( 0 === substr_compare( $html, '<!--', $lt, 4 ) ) {
			$close = strpos( $html, '-->', $lt );
			$i = false === $close ? $to : $close + 3;
			continue;
		}
		$open_end = nexxi_dom_tag_end( $html, $lt );
		if ( false === $open_end ) { break; }
		if ( ! preg_match( '~\G<([a-zA-Z][a-zA-Z0-9-]*)~', $html, $m, 0, $lt ) ) { $i = $open_end; continue; }
		$tag = strtolower( $m[1] );
		if ( nexxi_dom_is_void( $tag ) ) { $i = $open_end; continue; }
		$close = nexxi_dom_matching_close( $html, $tag, $open_end );
		$i = $close ? $close[1] : $to;
	}
	return $segments;
}

/** Replace the trimmed part of a raw text node, keeping its surrounding whitespace. */
function nexxi_studio_swap_text( $raw, $value ) {
	preg_match( '~^(\s*).*?(\s*)$~su', $raw, $m );
	return $m[1] . esc_html( $value ) . $m[2];
}

/** Apply text, image and placeholder edits. Runs on the pristine shell, before the screen modules. */
function nexxi_studio_apply_content( $html ) {
	if ( ! nexxi_studio_saved() ) { return $html; }
	// Text nodes (processed back to front so earlier offsets stay valid).
	if ( preg_match_all( '~ data-nxe="([^"]+)"~', $html, $matches, PREG_OFFSET_CAPTURE ) ) {
		for ( $n = count( $matches[0] ) - 1; $n >= 0; $n-- ) {
			$keys = explode( ',', $matches[1][ $n ][0] );
			$values = array();
			foreach ( $keys as $index => $key ) {
				if ( '-' !== $key && null !== ( $value = nexxi_studio_changed( $key ) ) ) { $values[ $index ] = $value; }
			}
			if ( ! $values ) { continue; }
			$attr_pos = $matches[0][ $n ][1];
			$start = strrpos( substr( $html, 0, $attr_pos ), '<' );
			$el = nexxi_dom_locate( $html, 'data-nxe="' . $matches[1][ $n ][0] . '"', $start );
			if ( ! $el || $el['start'] !== $start ) { continue; }
			$segments = nexxi_studio_segments( $html, $el['inner_start'], $el['inner_end'] );
			for ( $s = count( $segments ) - 1; $s >= 0; $s-- ) {
				if ( ! isset( $values[ $s ] ) ) { continue; }
				list( $a, $b ) = $segments[ $s ];
				$html = substr( $html, 0, $a ) . nexxi_studio_swap_text( substr( $html, $a, $b - $a ), $values[ $s ] ) . substr( $html, $b );
			}
		}
	}
	// Images and placeholders.
	foreach ( array( 'data-nxi' => 'src', 'data-nxp' => 'placeholder' ) as $hook => $attr ) {
		if ( ! preg_match_all( '~ ' . $hook . '="([^"]+)"~', $html, $found ) ) { continue; }
		foreach ( array_unique( $found[1] ) as $key ) {
			$value = nexxi_studio_changed( $key );
			if ( null === $value ) { continue; }
			$html = nexxi_dom_each( $html, $hook . '="' . $key . '"', static function ( $outer ) use ( $attr, $value ) {
				$open_end = nexxi_dom_tag_end( $outer, 0 );
				return nexxi_dom_tag_with_attr( substr( $outer, 0, $open_end ), $attr, $value ) . substr( $outer, $open_end );
			} );
		}
	}
	return $html;
}

/** Links, hidden regions, colours and socials. Runs after the screen modules. */
function nexxi_studio_apply_late( $html ) {
	if ( preg_match_all( '~ data-nxl="([^"]+)"~', $html, $found ) ) {
		foreach ( array_unique( $found[1] ) as $key ) {
			$url = nexxi_studio_url( nexxi_studio_opt( $key ) );
			if ( '' !== $url ) { $html = nexxi_dom_set_attr( $html, 'data-nxl="' . $key . '"', 'href', $url ); }
		}
	}
	foreach ( nexxi_studio_regions() as $region => $meta ) {
		if ( $meta[3] && ! nexxi_studio_region_visible( $region ) ) {
			$html = nexxi_dom_remove( $html, 'data-nxr="' . $region . '"' );
		}
	}
	$html = nexxi_studio_footer_social( $html );
	return nexxi_studio_apply_colors( $html );
}

/* ------------------------------------------------------------------ header */

function nexxi_studio_menu_defaults() {
	return array(
		1 => array( 'Trang Chủ', 'trang-chu', '', '' ),
		2 => array( 'Giới Thiệu', 'gioi-thieu', '', '' ),
		3 => array( 'Sản Phẩm', 'san-pham', 'Bé Yêu', 'soft' ),
		4 => array( 'Flash Sale', 'flash-sale', '⚡ Hot', 'hot' ),
		5 => array( 'Bảng Size', 'bang-size-cho-be', '', '' ),
		6 => array( 'Liên Hệ', 'lien-he', '', '' ),
		7 => array( '', '', '', '' ),
		8 => array( '', '', '', '' ),
	);
}

/** Menu items after edits: [label, path, url (custom or ''), badge, style]. */
function nexxi_studio_menu_items() {
	$items = array();
	foreach ( nexxi_studio_menu_defaults() as $n => $def ) {
		if ( '1' === nexxi_studio_opt( "menu_{$n}_hide" ) ) { continue; }
		$label = trim( nexxi_studio_opt( "menu_{$n}_label", $def[0] ) );
		if ( '' === $label ) { continue; }
		$items[] = array( $label, $def[1] ? $def[1] : 'custom-' . $n, nexxi_studio_url( nexxi_studio_opt( "menu_{$n}_url" ) ), trim( nexxi_studio_opt( "menu_{$n}_badge", $def[2] ) ), nexxi_studio_opt( "menu_{$n}_style", $def[3] ? $def[3] : 'soft' ) );
	}
	return $items;
}

function nexxi_studio_nbsp( $text ) {
	return str_replace( ' ', '&nbsp;', esc_html( $text ) );
}

/** Header edits (ticker, logo, label, menu, search). Runs before the shared header wiring. */
function nexxi_studio_header( $html ) {
	$el = nexxi_dom_locate( $html, '<header' );
	if ( ! $el ) { return $html; }
	$header = substr( $html, $el['start'], $el['end'] - $el['start'] );

	// Ticker.
	$ticker = nexxi_dom_locate( $header, '<div class="w-full bg-secondary-fixed' );
	if ( $ticker ) {
		$header = nexxi_dom_set_attr( $header, '<div class="w-full bg-secondary-fixed', 'data-nxr', 'header-ticker' );
		$lines = null !== nexxi_studio_changed( 'header-ticker__lines' ) ? preg_split( '~\R~u', nexxi_studio_value( 'header-ticker__lines' ) ) : null;
		if ( $lines ) {
			$lines = array_values( array_filter( array_map( 'trim', $lines ) ) );
			$spans = '';
			for ( $n = 0, $count = $lines ? max( 4, count( $lines ) ) : 0; $n < $count; $n++ ) { $spans .= '<span class="">' . esc_html( $lines[ $n % count( $lines ) ] ) . '</span>'; }
			$header = nexxi_dom_set_inner( $header, 'animate-marquee', $spans . $spans );
		}
	}

	// Brand: logo (header + footer use the same file) and label.
	$header = nexxi_dom_set_attr( $header, '<div class="flex items-center gap-space-md shrink-0', 'data-nxr', 'header-brand' );
	$label = nexxi_dom_locate( $header, '<span class="font-label-sm text-label-sm text-secondary tracking-normal' );
	if ( $label ) {
		$header = substr( $header, 0, $label['start'] ) . preg_replace( '~^<span~', '<span data-nxe="header-brand__label"', substr( $header, $label['start'], $label['open_end'] - $label['start'] ) ) . nexxi_studio_t( 'header-brand__label' ) . substr( $header, $label['inner_end'] );
	}

	// Menu.
	$nav = nexxi_dom_locate( $header, '<nav' );
	if ( $nav ) {
		$base = 'px-space-md py-space-xs rounded-full font-label-lg text-label-lg text-on-surface-variant hover:text-on-surface hover:bg-surface-container-highest transition-all duration-200';
		$badges = array(
			'soft' => 'text-[10px] bg-tertiary-fixed text-on-tertiary-fixed px-1.5 py-0.5 rounded-full font-bold',
			'hot'  => 'inline-flex items-center px-1.5 py-0.2 rounded-full text-[10px] font-bold bg-secondary text-on-secondary animate-pulse',
			'pink' => 'text-[10px] bg-secondary-fixed text-on-secondary-fixed px-1.5 py-0.5 rounded-full font-bold',
		);
		$links = '';
		foreach ( nexxi_studio_menu_items() as $item ) {
			list( $text, $path, $url, $badge, $style ) = $item;
			$class = $badge ? 'relative ' . $base . ' flex items-center gap-1.5' : $base;
			$href = $url ? ' href="' . esc_url( $url ) . '" data-href-fixed="1"' : ' href="#"';
			$links .= '<a class="' . esc_attr( $class ) . '" data-path="' . esc_attr( $path ) . '"' . $href . '>' . nexxi_studio_nbsp( $text ) . ( $badge ? ' <span class="' . esc_attr( isset( $badges[ $style ] ) ? $badges[ $style ] : $badges['soft'] ) . '">' . nexxi_studio_nbsp( $badge ) . '</span>' : '' ) . '</a>';
		}
		$open = substr( $header, $nav['start'], $nav['open_end'] - $nav['start'] );
		$open = nexxi_dom_tag_with_attr( $open, 'data-nxr', 'header-menu' );
		$header = substr( $header, 0, $nav['start'] ) . $open . $links . substr( $header, $nav['inner_end'] );
	}

	// Search.
	$header = nexxi_dom_set_attr( $header, '<div class="hidden md:flex items-center bg-surface-container-low rounded-full', 'data-nxr', 'header-search' );
	$header = nexxi_dom_each( $header, '<input', static function ( $outer ) {
		$outer = nexxi_dom_tag_with_attr( $outer, 'placeholder', nexxi_studio_value( 'header-search__p' ) );
		return preg_replace( '~^<input\b~', '<input data-nxp="header-search__p"', $outer, 1 );
	} );

	$html = substr( $html, 0, $el['start'] ) . $header . substr( $html, $el['end'] );

	// Logo everywhere (header + footer).
	$html = str_replace( '<img alt="logo.jpg"', '<img data-nxi="header-brand__logo" alt="logo.jpg"', $html );
	$logo = nexxi_studio_changed( 'header-brand__logo' );
	if ( $logo ) { $html = str_replace( '{{STITCH_ASSET}}/images/logo.jpg', esc_url( $logo ), $html ); }
	return $html;
}

/* ------------------------------------------------------------------ footer */

/** The approved home footer, reused on every screen so one edit applies everywhere. */
function nexxi_studio_shared_footer() {
	static $footer = null;
	if ( null === $footer ) {
		$file = get_template_directory() . '/assets/stitch/pages/index.html';
		$footer = is_readable( $file ) ? nexxi_dom_get_outer( file_get_contents( $file ), '<footer' ) : ''; // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	}
	return $footer;
}

