/** Social buttons replace the three decorative footer icons once at least one link is set. */
function nexxi_studio_footer_social( $html ) {
	$needle = '<div class="flex items-center gap-space-sm pt-space-xs">';
	$footer = nexxi_dom_locate( $html, '<footer' );
	if ( ! $footer || false === strpos( substr( $html, $footer['start'], $footer['end'] - $footer['start'] ), $needle ) ) { return $html; }
	$html = nexxi_dom_set_attr( $html, $needle, 'data-nxr', 'footer-social' );
	$buttons = '';
	foreach ( nexxi_studio_socials() as $key => $social ) {
		$value = trim( nexxi_studio_opt( 'social_' . $key ) );
		if ( '' === $value ) { continue; }
		if ( 'zalo' === $key && preg_match( '~^[\d\s.+]+$~', $value ) ) { $value = 'https://zalo.me/' . preg_replace( '~\D~', '', $value ); }
		$buttons .= '<a class="w-9 h-9 rounded-full bg-surface-container-lowest flex items-center justify-center text-secondary shadow-sm hover:scale-105 transition-all" href="' . esc_url( $value ) . '" target="_blank" rel="noopener" aria-label="' . esc_attr( $social[0] ) . '">' . $social[1] . '</a>';
	}
	return $buttons ? nexxi_dom_set_inner( $html, 'data-nxr="footer-social"', $buttons ) : $html;
}

/* ------------------------------------------------------------------ colours */

/** setting => [label, tailwind tokens, original hex]. */
function nexxi_studio_colors() {
	return array(
		'color_primary'   => array( 'Màu chính (chữ tiêu đề, nút đậm)', array( 'primary' ), '#031444' ),
		'color_primary2'  => array( 'Màu chính – biến thể', array( 'primary-container' ), '#1b2a59' ),
		'color_secondary' => array( 'Màu nhấn đậm (giá, nút Mua)', array( 'secondary' ), '#ae3115' ),
		'color_accent'    => array( 'Màu nhấn sáng (cam san hô)', array( 'secondary-container' ), '#fd6a49' ),
		'color_soft'      => array( 'Màu nền nhãn / thanh thông báo (hồng phấn)', array( 'secondary-fixed' ), '#ffdad2' ),
		'color_tertiary'  => array( 'Màu phụ (vàng kem)', array( 'tertiary-fixed' ), '#ffddb8' ),
		'color_bg'        => array( 'Màu nền trang', array( 'background', 'surface', 'surface-bright' ), '#fbf9f5' ),
		'color_text'      => array( 'Màu chữ nội dung', array( 'on-surface', 'on-background' ), '#1b1c1a' ),
	);
}

/** original hex => new hex for every changed colour. */
function nexxi_studio_color_map() {
	$map = array();
	foreach ( nexxi_studio_colors() as $key => $color ) {
		$value = sanitize_hex_color( nexxi_studio_opt( $key ) );
		if ( $value && strtolower( $value ) !== $color[2] ) { $map[ $color[2] ] = strtolower( $value ); }
	}
	return $map;
}

function nexxi_studio_apply_colors( $html ) {
	foreach ( nexxi_studio_colors() as $key => $color ) {
		$value = sanitize_hex_color( nexxi_studio_opt( $key ) );
		if ( ! $value || strtolower( $value ) === $color[2] ) { continue; }
		foreach ( $color[1] as $token ) {
			$html = preg_replace( '~("' . preg_quote( $token, '~' ) . '":\s*")#[0-9a-fA-F]{6}(")~', '${1}' . $value . '${2}', $html, 1 );
		}
	}
	return $html;
}

/** Stitch stylesheet tag; inlined with the brand colours when they were changed. */
function nexxi_studio_stylesheet_tag( $url, $file ) {
	$map = nexxi_studio_color_map();
	if ( ! $map || ! is_readable( $file ) ) { return '<link rel="stylesheet" href="' . esc_url( $url ) . '">'; }
	$css = str_ireplace( array_keys( $map ), array_values( $map ), file_get_contents( $file ) ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	return '<style id="nexxi-stitch-css">' . $css . '</style>';
}
